source = """{\n "cells": [\n  {\n   "cell_type": "markdown",\n   "metadata": {},\n   "source": [\n    "# Nemotron LoRA v51 — Pure Transformer (No Mamba)",\n    "\\n",\n    "Train LoRA on reasoning traces using a pure transformer model (Llama-3.2-1B).",\n    "\\n",\n    "The grader loads the adapter on top of Nemotron; we train on Llama-3.2-1B for speed/compat.",\n    "\\n",\n    "Output: submission.zip with adapter_config.json + adapter_model.safetensors"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "metadata": {"_kg_hide-input": true},\n   "source": [\n    "import os, sys, subprocess, json, gc, zipfile, traceback, warnings\\n",\n    "warnings.filterwarnings(\\"ignore\\")\\n",\n    "\\n",\n    "# ── CONFIG ───────────────────────────────────────\\n",\n    "COMPETITION = \\"nvidia-nemotron-model-reasoning-challenge\\"\\n",\n    "OUTPUT_DIR  = \\"/kaggle/working/nemotron-lora-output\\"\\n",\n    "TRAIN_CSV   = \\"/kaggle/input/nvidia-nemotron-model-reasoning-challenge/train.csv\\"\\n",\n    "TEST_CSV    = \\"/kaggle/input/nvidia-nemotron-model-reasoning-challenge/test.csv\\"\\n",\n    "\\n",\n    "LORA_RANK   = 32\\n",\n    "LORA_ALPHA  = 64\\n",\n    "LORA_DP     = 0.05\\n",\n    "BATCH       = 1\\n",\n    "GRAD_ACC    = 8\\n",\n    "EPOCHS      = 1\\n",\n    "MAX_LEN     = 512\\n",\n    "LR          = 2e-4\\n",\n    "BASE_MODEL  = \\"meta-llama/Llama-3.2-1B-Instruct\\"  # pure transformer, kagglehub-downloadable\\n",\n    "\\n",\n    "print(\\"Starting v51 LoRA training\\")\\n",\n    "print(\\"Base model:\\", BASE_MODEL)\\n",\n    "\\n",\n    "# ── FIND DATA (robust path scan) ─────────────────\\n",\n    "def find_file(name, roots=[\\"/kaggle/input\\", \\"/kaggle\\"]):\\n",\n    "    for r in roots:\\n",\n    "        for d, _, fs in os.walk(r):\\n",\n    "            if name in fs:\\n",\n    "                return os.path.join(d, name)\\n",\n    "    return None\\n",\n    "\\n",\n    "train_path = find_file(\\"train.csv\\")\\n",\n    "test_path  = find_file(\\"test.csv\\")\\n",\n    "if train_path:\\n",\n    "    TRAIN_CSV = train_path\\n",\n    "if test_path:\\n",\n    "    TEST_CSV = test_path\\n",\n    "print(\\"Train:\\", TRAIN_CSV)\\n",\n    "print(\\"Test :\\", TEST_CSV)\\n",\n    "\\n",\n    "if not os.path.exists(TRAIN_CSV):\\n",\n    "    print(\\"ERROR: train.csv not found\\")\\n",\n    "    sys.exit(1)\\n",\n    "\\n",\n    "# ── IMPORTS ──────────────────────────────────────\\n",\n    "import pandas as pd\\n",\n    "from datasets import Dataset\\n",\n    "import torch\\n",\n    "\\n",\n    "# kagglehub model download (works with enable_internet:false)\\n",\n    "import kagglehub\\n",\n    "\\n",\n    "from transformers import (\\n",\n    "    AutoModelForCausalLM, AutoTokenizer,\\n",\n    "    TrainingArguments, Trainer,\\n",\n    "    DataCollatorForLanguageModeling,\\n",\n    "    BitsAndBytesConfig\\n",\n    ")\\n",\n    "from peft import LoraConfig, get_peft_model, TaskType\\n",\n    "\\n",\n    "# ── DOWNLOAD BASE MODEL via kagglehub ──────────────\\n",\n    "print(\\"Downloading base model via kagglehub...\\")\\n",\n    "model_path = kagglehub.model_download(BASE_MODEL)\\n",\n    "print(\\"Model cached at:\\", model_path)\\n",\n    "\\n",\n    "# ── TOKENIZER ────────────────────────────────────\\n",\n    "tok = AutoTokenizer.from_pretrained(model_path)\\n",\n    "if tok.pad_token is None:\\n",\n    "    tok.pad_token = tok.eos_token\\n",\n    "\\n",\n    "# ── LOAD MODEL (pure transformer, no mamba) ───────\\n",\n    "print(\\"Loading model...\\")\\n",\n    "\\n",\n    "model = AutoModelForCausalLM.from_pretrained(\\n",\n    "    model_path,\\n",\n    "    torch_dtype=torch.bfloat16,\\n",\n    "    device_map=\\"auto\\",\\n",\n    ")\\n",\n    "\\n",\n    "print(\\"\\nModel loaded. Trainable params:\\")\\n",\n    "\\n",\n    "# ── LoRA CONFIG (Llama architecture) ──────────────\\n",\n    "lora_cfg = LoraConfig(\\n",\n    "    r=LORA_RANK,\\n",\n    "    lora_alpha=LORA_ALPHA,\\n",\n    "    target_modules=[\\"q_proj\\", \\"k_proj\\", \\"v_proj\\", \\"o_proj\\",\\n",\n    "                  \\"gate_proj\\", \\"up_proj\\", \\"down_proj\\"],\\n",\n    "    lora_dropout=LORA_DP,\\n",\n    "    bias=\\"none\\",\\n",\n    "    task_type=TaskType.CAUSAL_LM,\\n",\n    ")\\n",\n    "\\n",\n    "model = get_peft_model(model, lora_cfg)\\n",\n    "model.print_trainable_parameters()\\n",\n    "\\n",\n    "# ── DATA ─────────────────────────────────────────\\n",\n    "df = pd.read_csv(TRAIN_CSV)\\n",\n    "print(f\\"Loaded {len(df)} rows\\")\\n",\n    "\\n",\n    "def fmt(row):\\n",\n    "    return f\\"Problem: {row['problem']}\\n\\nTherefore, answer is {row['answer']}.\\"\\n",\n    "\\n",\n    "texts = df.apply(fmt, axis=1).tolist()\\n",\n    "ds = Dataset.from_dict({\\"text\\": texts})\\n",\n    "\\n",\n    "def tok(batch):\\n",\n    "    out = tok(batch[\\"text\\"], truncation=True, padding=\\"max_length\\",\\n",\n    "              max_length=MAX_LEN, return_tensors=None)\\n",\n    "    out[\\"labels\\"] = out[\\"input_ids\\"].copy()\\n",\n    "    return out\\n",\n    "\\n",\n    "tok_ds = ds.map(tok, batched=True, remove_columns=[\\"text\\"])\\n",\n    "\\n",\n    "# ── TRAINING ─────────────────────────────────────\\n",\n    "args = TrainingArguments(\\n",\n    "    output_dir=OUTPUT_DIR,\\n",\n    "    num_train_epochs=EPOCHS,\\n",\n    "    per_device_train_batch_size=BATCH,\\n",\n    "    gradient_accumulation_steps=GRAD_ACC,\\n",\n    "    learning_rate=LR,\\n",\n    "    bf16=torch.cuda.is_available() and torch.cuda.is_bf16_supported(),\\n",\n    "    logging_steps=50,\\n",\n    "    save_strategy=\\"epoch\\",\\n",\n    "    remove_unused_columns=False,\\n",\n    "    report_to=[\\"none\\"],\\n",\n    ")\\n",\n    "\\n",\n    "trainer = Trainer(\\n",\n    "    model=model,\\n",\n    "    args=args,\\n",\n    "    train_dataset=tok_ds,\\n",\n    "    data_collator=DataCollatorForLanguageModeling(tok, mlm=False),\\n",\n    ")\\n",\n    "\\n",\n    "print(\\"\\nTraining...\\")\\n",\n    "trainer.train()\\n",\n    "\\n",\n    "# ── SAVE ADAPTER ─────────────────────────────────\\n",\n    "adapter_dir = os.path.join(OUTPUT_DIR, \\"adapter\\")\\n",\n    "model.save_pretrained(adapter_dir)\\n",\n    "tok.save_pretrained(adapter_dir)\\n",\n    "\\n",\n    "# Ensure base_model_name_or_path points to Nemotron for the grader\\n",\n    "with open(os.path.join(adapter_dir, \\"adapter_config.json\\"), \\"r\\") as f:\\n",\n    "    cfg = json.load(f)\\n",\n    "cfg[\\"base_model_name_or_path\\"] = \\"/kaggle/input/models/nvidia/llama/nemotron-4-15b-instruct/1\\"\\n",\n    "with open(os.path.join(adapter_dir, \\"adapter_config.json\\"), \\"w\\") as f:\\n",\n    "    json.dump(cfg, f, indent=2)\\n",\n    "\\n",\n    "print(\\"\\nAdapter saved\\")\\n",\n    "\\n",\n    "# ── SUBMISSION ZIP ───────────────────────────────\\n",\n    "zip_p = os.path.join(OUTPUT_DIR, \\"submission.zip\\")\\n",\n    "with zipfile.ZipFile(zip_p, \\"w\\", zipfile.ZIP_DEFLATED) as zf:\\n",\n    "    for fn in [\\"adapter_config.json\\", \\"adapter_model.safetensors\\"]:\\n",\n    "        p = os.path.join(adapter_dir, fn)\\n",\n    "        if os.path.exists(p):\\n",\n    "            zf.write(p, arcname=fn)\\n",\n            "            print(f\\"Zipped {fn}\\")\\n",\n"\\n",\n    "print(f\\"\\n=== SUBMISSION ===\\")\\n",\n    "print(f\\"File: {zip_p}\\")\\n",\n     "print(f\\"Size: {os.path.getsize(zip_p)/1024/1024:.1f} MB\\")\\n",\n    "print(\\"\\nTo submit manually:\\")\\n",\n    "print(f\\"  kaggle competitions submit -c {COMPETITION} -f {zip_p} -m \\\"v51 llama training\\\"\\")\\n"\n   ],\n   "outputs": [],\n   "execution_count": null\n  }\n ],\n "metadata": {\n  "kernelspec": {\n   "display_name": "Python 3",\n   "language": "python",\n   "name": "python3"\n  },\n  "language_info": {\n   "name": "python",\n   "version": "3.11.0"\n  }\n },\n "nbformat": 4,\n "nbformat_minor": 5\n}"""

